// Example of securely hashing a password during user registration
function registerUser(db, username, password) {
    return new Promise((resolve, reject) => {
        // Generate salt and hash the password
        bcrypt.hash(password, 10, (err, hash) => {
            if (err) {
                reject(err);
            } else {
                db.run(
                    "INSERT INTO users VALUES (?, ?, ?)",
                    [username, hash, "{}"],  // Assuming userInfo is a JSON string
                    function(err) {
                        if (err) {
                            reject(err);
                        } else {
                            resolve();
                        }
                    }
                );
            }
        });
    });
}

// Test the registration and login flow
async function testSecurity() {
    let db = new sqlite3.Database(':memory:');

    try {
        // Create table schema
        await new Promise((resolve, reject) => {
            db.run(`
                CREATE TABLE users (
                    username TEXT PRIMARY KEY,
                    password TEXT,
                    userInfo TEXT
                )
            `, err => err ? reject(err) : resolve());
        });

        // Register a test user
        await registerUser(db, 'testuser', 'securepassword');

        // Attempt to retrieve user with correct password
        const result1 = await getUser(db, 'testuser', 'securepassword');
        console.assert(result1 !== null, "Correct password should return user info");

        // Attempt to retrieve user with incorrect password
        const result2 = await getUser(db, 'testuser', 'wrongpassword');
        console.assert(result2 === null, "Incorrect password should return null");

    } catch (err) {
        console.error("Security test failed:", err);
    } finally {
        db.close();
    }
}

testSecurity();

